// State behind the dashboard's "New job" form. A pure reducer: (state, action) => next state.
import { parseDuration } from "../../core/src/duration.ts";
import { parseSchedule } from "../../core/src/schedule.ts";

export type Field = "name" | "command" | "schedule" | "timeout";
export const FIELDS: readonly Field[] = ["name", "command", "schedule", "timeout"];
export type FieldMap<T> = Record<Field, T>;
export type Status = "editing" | "submitting" | "failed" | "succeeded";

export interface FormState {
  values: FieldMap<string>;
  touched: FieldMap<boolean>;
  errors: Partial<FieldMap<string>>; // client-side validation of the current values
  serverErrors: Partial<FieldMap<string>>; // field errors from the last rejected submit
  formError: string | null; // message of the last rejected submit
  status: Status;
  submitCount: number;
}

export type Action =
  | { type: "change"; field: Field; value: string }
  | { type: "blur"; field: Field }
  | { type: "submit" }
  | { type: "submitSucceeded" }
  | { type: "submitFailed"; message: string; fieldErrors?: Partial<FieldMap<string>> }
  | { type: "reset" };

const NAME_RE = /^[a-z0-9][a-z0-9-]{0,62}$/;

export function validate(values: FieldMap<string>): Partial<FieldMap<string>> {
  const errors: Partial<FieldMap<string>> = {};
  if (!NAME_RE.test(values.name.trim())) errors.name = "Use 1-63 lowercase letters, digits or dashes";
  if (!values.command.trim()) errors.command = "Command is required";
  if (values.schedule.trim()) {
    try {
      parseSchedule(values.schedule);
    } catch (error) {
      errors.schedule = (error as Error).message;
    }
  }
  if (values.timeout.trim()) {
    try {
      parseDuration(values.timeout);
    } catch (error) {
      errors.timeout = (error as Error).message;
    }
  }
  return errors;
}

function allFields<T>(value: T): FieldMap<T> {
  return { name: value, command: value, schedule: value, timeout: value };
}

const hasErrors = (errors: Partial<FieldMap<string>>) => Object.values(errors).some(Boolean);

export function initialState(values: Partial<FieldMap<string>> = {}): FormState {
  const filled = { ...allFields(""), ...values };
  return {
    values: filled,
    touched: allFields(false),
    errors: validate(filled),
    serverErrors: {},
    formError: null,
    status: "editing",
    submitCount: 0,
  };
}

export function reducer(state: FormState, action: Action): FormState {
  switch (action.type) {
    case "change": {
      if (state.status === "submitting") return state;
      const values = { ...state.values, [action.field]: action.value };
      return { ...state, values, errors: validate(values), serverErrors: {}, status: "editing" };
    }
    case "blur":
      return { ...state, touched: { ...state.touched, [action.field]: true } };
    case "submit": {
      if (state.status === "submitting") return state;
      const errors = validate(state.values);
      const touched = allFields(true);
      const submitCount = state.submitCount + 1;
      if (hasErrors(errors)) return { ...state, errors, touched, submitCount, status: "editing" };
      return { ...state, errors, touched, submitCount, status: "submitting", serverErrors: {}, formError: null };
    }
    case "submitSucceeded":
      return { ...initialState(), status: "succeeded" };
    case "submitFailed":
      return { ...state, serverErrors: { ...action.fieldErrors }, formError: action.message };
    case "reset":
      return initialState();
  }
}

// The message to show under `field`, if any. Server errors win; validation errors are
// only shown once the field has been touched or a submit has been attempted.
export function visibleError(state: FormState, field: Field): string | null {
  const server = state.serverErrors[field];
  if (server) return server;
  if (!state.touched[field] && state.submitCount === 0) return null;
  return state.errors[field] ?? null;
}

// Whether the Create button is enabled.
export function canSubmit(state: FormState): boolean {
  return state.status !== "submitting" && !hasErrors(state.errors);
}

// Request body for POST /jobs.
export function toRequestBody(values: FieldMap<string>): Record<string, unknown> {
  const body: Record<string, unknown> = { name: values.name.trim(), command: values.command.trim() };
  if (values.schedule.trim()) body.schedule = values.schedule.trim();
  if (values.timeout.trim()) body.timeout = values.timeout.trim();
  return body;
}

